.ql-editor .mrw-implicit {
    background-color: var(--mrw-implicit-bg-color);
}
.ql-editor .mrw-indirect {
    background-color: var(--mrw-indirect-bg-color);
}
.ql-editor .mrw-mflag {
    background-color: var(--mrw-mflag-bg-color);
